// WF-03 · Restauración del payload tras persistir el veredicto.
//
// Mismo motivo que en WF-01: el UPDATE de Postgres deja su propio resultado
// en el item. Sin restaurar, el Switch evaluaría $json.triage.verdict sobre
// un objeto que no lo tiene, caería siempre por la rama de respaldo y TODA
// alerta acabaría en "investigar" — incluidas las críticas.

return [{ json: $('Puntuar y decidir').first().json }];
